export type ILoggerEnv = {
  /** Boolean process.stdout.isTTY at construction, false when unavailable. */ readonly isTTY: boolean;
  /** Boolean process.env.CI at construction, false when unavailable. */ readonly isCI: boolean;
};

export type ILoggerOptions<
  P extends readonly ILoggerPluginConstraint[] = [],
  TMode extends IMiddlewarePipelineMode = 'sync',
> = {
  /** Explicit PluginHost operation and drain budgets; `false` opts into unbounded waiting. */ execution: IPluginHostOptions['execution'];
  /** Host capability owner; omitted means capture the current module default at construction. */ runtimeManager?: ILoggerRuntimeManager;
  /** Optional prefix path, copied/frozen at construction; defaults to an empty array. */ context?: string[];
  /** Forwarding display topic; defaults to an empty string and is not a uniqueness token. */ topic?: string;
  /** Constructor hooks, defaulting to none; equivalent to core.hook(name, fn) for each entry. */ on?: Record<
    string,
    ILogHookFn
  >;
  /** Constructor-installed plugins, defaulting to an empty list; failures roll back Host admission. */ plugins?: P;
  /** * Custom application options exposed through `core.ctx.options` to every plugin. Framework fields * such as `context`, `on`, and `plugins` have separate roles and are not included here. Defaults * to an empty record; only the copied top-level record is frozen. */ options?: Record<
    string,
    unknown
  >;
  /** Optional runner; mode defaults to sync and also accepts async, generator or async-generator. */ pipeline?: IPluginHostOptions['pipeline'] & {
    mode?: TMode;
  };
  /** * Defaults to utils/scheduler `systemScheduler`. Flush, shutdown, and batch deadlines share its * clock domain. */ scheduler?: IScheduler;
};

export type ILoggerPluginConfig = {
  /** Read the current host-owned immutable configuration snapshot for this plugin only. */ get<
    T extends IPluginConfig = IPluginConfig,
  >(): Readonly<T>;
};

export type ILoggerPluginCore<
  TMode extends IPipelineConfig['mode'] = IMiddlewarePipelineMode,
  TShared extends Record<string, unknown> = Record<string, never>,
> = Omit<ILoggerCore<TMode, TShared>, 'use' | 'unUse' | 'onDispose'> & {
  /** Register an install-owned resource; Host removal/disposal releases it in reverse order. */ onDispose(
    resource: import('@migaia/plugin-host').IPluginResource,
  ): void;
  /** Reports durable observer and resource failures through the original logger policy. */ reportFailure(
    failure: ILogFailure,
  ): void;
};

export type ILoggerProcess = {
  /** Environment values used by output detection and process policy. */ readonly env: Readonly<
    Record<string, string | undefined>
  >;
  /** Borrowed output stream used for host detection and raw writes. */ readonly stdout: {
    /** Optional terminal flag; absence behaves as a non-TTY host. */ readonly isTTY?: boolean;
    /** Write raw text using the host's own buffering/error policy. */ write(
      value: string,
    ): unknown;
  };
  /** Attach a process event listener; failed installation participates in plugin rollback. */ on(
    event: string,
    listener: (...args: any[]) => void,
  ): unknown;
  /** Detach the exact owned event listener during rollback or final plugin release. */ removeListener(
    event: string,
    listener: (...args: any[]) => void,
  ): unknown;
  /** Original terminal host operation; interception is opt-in and changes its timing. */ exit: (
    code?: number,
  ) => never;
};

export type ILoggerRuntimeManager = {
  /** Optional process surface; absent hosts make the process plugin inert. */ readonly process?: ILoggerProcess;
  /** Optional injected file sink; absent by default in every runtime. */ readonly fs?: {
    /** Append one newline-delimited JSON batch; rejection is reported as file delivery failure. */ append(
      path: string,
      text: string,
    ): Promise<void>;
    /** Optional rotation after the current batch crosses a configured threshold. */ rotate?(
      path: string,
    ): Promise<void>;
  };
  /** * Optional host cancellation factory for alternate AbortSignal implementations; native fallback * when absent. */ readonly createAbortController?: () => AbortController;
  /** * Generate Logger context and UUID-plugin identities; this does not establish cryptographic * trust. */ randomUUID(): string;
  /** Schedule a callback outside the current stack; Logger tracks its actual completion separately. */ defer(
    task: () => void,
  ): void;
  /** Write raw text; synchronous failures can propagate from Logger.raw(). */ write(
    text: string,
  ): void;
  /** Optional console surface; an absent console uses the manager's write fallback. */ readonly console?: {
    /** Receive ordinary/debug/info output without reconstructing native arguments. */ log(
      ...args: unknown[]
    ): void;
    /** Receive warn-tag output from the color sink. */ warn(...args: unknown[]): void;
    /** Receive error/fatal output and terminal Logger diagnostics. */ error(
      ...args: unknown[]
    ): void;
  };
  /** Optional HTTP capability; absence makes attempted HTTP delivery fail TRANSPORT_UNAVAILABLE. */ fetch?: (
    input: string,
    init: {
      /** HTTP verb chosen by the delivery plugin. */ method: string;
      /** Resolved request headers, including optional bearer authentication. */ headers: Record<
        string,
        string
      >;
      /** Serialized complete entry batch. */ body: string;
      /** Optional plugin-owned request/shutdown cancellation signal. */ signal?: AbortSignal;
    },
  ) => Promise<{
    /** Host success classification; failed responses follow retry/delivery policy. */ readonly ok: boolean;
    /** HTTP status used to select retryable responses. */ readonly status: number;
    /** Response metadata used for Retry-After policy. */ readonly headers: {
      /** Return the response header value or null when absent. */ get(
        name: string,
      ): string | null;
    };
  }>;
};

export type IPipelineStage = (
  entry: ILogEntry,
  next: (entry: ILogEntry) => void,
) => void;

export type IRawEntryInput = Partial<Omit<ILogEntry, 'id'>> & {
  /** Required general label, interpreted by installed plugins. */ tag: string;
  /** Required message; nonstring level arguments are carried separately by that plugin. */ message: string;
};

export type IShutdownReason =
  | 'signal'
  | 'uncaughtException'
  | 'unhandledRejection'
  | 'manual';

export type IStaticLoggerCtor = {
  /** * Construct with required explicit execution budgets and optional plugins. Invalid construction * or plugin admission throws before exposure. No output sink or level methods are installed by * default; returned extension methods are inferred from the constructor's plugin tuple. */ new <
    const LocalP extends readonly ILoggerPluginConstraint[] = readonly [],
    const TMode extends IMiddlewarePipelineMode = 'sync',
  >(
    options: ILoggerOptions<LocalP, TMode>,
  ): Omit<ILoggerCore<TMode, IResolvedPluginShared<LocalP>>, 'config' | 'onDispose'> & {
    readonly config: ILoggerConfig;
  } & IMergePluginExts<LocalP>;
};

examples:
import { Logger } from '@migaia/logger'

const log = new Logger({
  execution: { mutationTimeoutMs: false, pipelineDrainTimeoutMs: false },
  context: ['checkout']
})
log.useSink((entry) => {
  console.log(entry.context.join('.'), entry.message, entry.meta?.orderId)
})
log.dispatchRaw({ tag: 'audit', message: '订单已保存', meta: { orderId: 'A-17' } })
await log.shutdown('manual')

import { Logger } from '@migaia/logger'

const log = new Logger({
  execution: { mutationTimeoutMs: false, pipelineDrainTimeoutMs: false }
})
const details = { count: 1 }
log.useSink((entry) => {
  entry.data.route = 'changed'
  ;(entry.args[0] as { count: number }).count = 2
})
log.useSink((entry) => {
  console.log(entry.data.route, (entry.args[0] as { count: number }).count)
})
log.dispatchRaw({ tag: 'audit', message: 'checkout', data: { route: 'original' }, args: [details] })
console.log(details.count)
await log.shutdown('manual')

import { Logger } from '@migaia/logger'

const log = new Logger({
  execution: { mutationTimeoutMs: false, pipelineDrainTimeoutMs: false }
})
const saved: string[] = []
log.useSink(async (entry) => {
  await Promise.resolve()
  saved.push(entry.message)
})
log.log('audit', '已保存')
console.log(saved.length)
await log.flush()
console.log(saved.length, saved[0])
await log.shutdown('manual')

import { Logger } from '@migaia/logger'

const log = new Logger({
  execution: { mutationTimeoutMs: false, pipelineDrainTimeoutMs: false }
})
const entries: string[] = []
log.useSink((entry) => {
  entries.push(entry.message)
})
log.onShutdown(() => {
  log.log('audit', '最后一条')
})
const closing = log.shutdown('manual')
console.log(closing === log.dispose())
await closing
log.log('audit', '关闭后')
console.log(entries.join(','))

import { Logger, getLoggerRuntimeManager } from '@migaia/logger'
import { color } from '@migaia/logger/plugins'

const lines: string[] = []
const capture = (...args: unknown[]): void => {
  lines.push(String(args[0]))
}
const log = new Logger({
  execution: { mutationTimeoutMs: false, pipelineDrainTimeoutMs: false },
  context: ['checkout'],
  runtimeManager: {
    ...getLoggerRuntimeManager(),
    console: { log: capture, warn: capture, error: capture }
  },
  plugins: [color({ format: 'json' })]
})
const original = new Error('余额不足')
log.log('error', '结账失败', original)
await log.flush()
const entry = JSON.parse(lines[0]!)
console.log(entry.tag, entry.context, entry.error.name, entry.error.message)
console.log(typeof entry.error.stack === 'string', Object.hasOwn(entry.error, 'raw'))
await log.shutdown('manual')

import { Logger } from '@migaia/logger'
import { binlog, wal, undoLog, memoryLogStore } from '@migaia/logger/plugins/durable'

await using events = memoryLogStore()
await using intents = memoryLogStore()
await using images = memoryLogStore()
const log = new Logger({
  execution: { mutationTimeoutMs: false, pipelineDrainTimeoutMs: false },
  plugins: [binlog({ store: events }), wal({ store: intents }), undoLog({ store: images })]
})
try {
  await Promise.all([log.binlog.ready(), log.wal.ready(), log.undo.ready()])
  const seq = await log.binlog.append('order.created', { id: 'o1' })
  const off = log.binlog.subscribe(seq, (record) => console.log(record.seq))
  const intent = await log.wal.begin('save-order', { id: 'o1' })
  await log.undo.record('tx1', [{ target: 'o1', before: null, after: { total: 120 } }])
  await log.wal.complete(intent)
  console.log(await log.undo.get('tx1'))
  await log.undo.forget('tx1')
  off()
} finally {
  try {
    await log.shutdown('manual')
  } finally {
    await Promise.all([log.binlog.whenIdle(), log.wal.whenIdle(), log.undo.whenIdle()])
  }
}

