export type IBatcher<T> = {
  /** Buffer an item; overflow is reported with dropped counts, and a disposed batcher ignores input. */ push(
    item: T,
  ): void;
  /** * Drain buffer/queue until its flushTimeoutMs budget; timeout does not cancel in-flight * callbacks. */ flush(): Promise<void>;
};

export type IBatchPluginConfig = {
  /** Size-triggered batch threshold, defaulting to 20 items. */ maxSize?: number;
  /** Delay from the first buffered item to timer-triggered flushing, defaulting to 2000 ms. */ maxWaitMs?: number;
  /** Maximum number of batches executing at once. Defaults to one for lossless delivery. */ maxConcurrentBatches?: number;
  /** * Maximum number of queued or executing batches. Defaults to 1024. A full batch beyond it drops * the oldest queued batch and reports `BATCH_OVERFLOW` with `detail.dropped`. */ maxPendingBatches?: number;
  /** * Time budget in milliseconds for one `flush()` drain, including the drain on dispose. Defaults * to 3000. Entries still buffered or queued when dispose reaches it are dropped and reported. */ flushTimeoutMs?: number;
  /** * Schedules a full-batch callback asynchronously when enabled. Defaults to `true`; * timer-triggered callbacks are already asynchronous. */ asyncOutput?: boolean;
};

export type IBatchShared = {
  /** Create a queue whose callback jobs and cleanup remain owned by this provider installation. */ createBatcher: ICreateBatcher;
};

export type IColorPluginConfig = {
  /** Defaults to auto; `always` forces ANSI and `never` disables it, regardless of host detection. */ color?: ILoggerColorMode;
  /** Defaults to auto: LOG_FORMAT wins, then CI/TTY selects pretty, otherwise json. */ format?: IOutputFormat;
  /** Defaults to true for pretty output; JSON always keeps its structured time field. */ timestamp?: boolean;
  /** * Message argument coloring range. Defaults to `none`, leaving the message and its arguments * uncolored. head colors the message; tail colors the last argument or an argument-free message; * head-tail combines them; all colors the message and primitive arguments, preserving objects. */ colorMessage?:
    | 'head'
    | 'tail'
    | 'head-tail'
    | 'all'
    | 'none';
