    string,
    (text: string) => string
  >;
};

export type ICreateBatcher = <T>(
  config: IBatchPluginConfig,
  onBatch: (items: T[]) => void | Promise<void>,
) => IBatcher<T>;

export type IHttpPluginConfig = {
