  version: 1,
  state: { items: [] as readonly ICartItem[], byId: keyed<ICartItem>() },
  computed: { total: (s) => s.items.reduce((sum, item) => sum + item.price, 0) },
  commands: {
    add: (s, item: ICartItem) => ({ items: [...s.items, item], byId: { [item.id]: item } })
  },
  writers: ['product'],
