export declare const PluginHostRegistrationLifecycle: {
  /** No installation/disposal hook is currently acquiring registration resources. */ readonly idle: 'idle';
  /** Current install attempt may acquire resources and stages before publication. */ readonly install: 'install';
  /** Registration capabilities are being revoked and released; new acquisition is rejected. */ readonly dispose: 'dispose';
};

export declare const PluginHostStatus: {
  /** Accepts new operations; existing registrations can publish through their normal guards. */ readonly active: 'active';
  /** Disposal closed admission; accepted work and cleanup may still be settling. */ readonly closing: 'closing';
  /** Logical terminal state; physicalCompletion can still describe outstanding cleanup. */ readonly disposed: 'disposed';
};

export declare const readPluginDependencies: (
  plugin: unknown,
) => readonly IPluginDependency[];

export declare const readPluginHostDisposalProvenance: (
  value: unknown,
) => IPluginHostDisposalProvenance | undefined;

export declare const createView: <TPlugin extends IPluginConstraint<any>>(
  token: IRegistrationToken<TPlugin>,
) => IRegistrationView<TPlugin>;

export declare const inspectFeatures: <TFeatures extends IFeatureRecord>(
  roots: TFeatures,
) => IFeatureInspection<TFeatures>;

export type IPluginHostCompositionIntegration<_THost> = Readonly<{
  /** Live committed revision, used to reject publication of a drifted prepared candidate. */ readonly revision: number;
  /** Captures current enabled publication; throws when the Host no longer accepts access. */ getCurrentSnapshot(): IPluginHostCompositionSnapshot;
  /** Captures a definition without running hooks and returns its immutable opaque admission. */ createPluginAdmission<
    TPlugin extends IPluginConstraint<any>,
  >(
    plugin: TPlugin,
  ): IPluginAdmission<TPlugin>;
  /** Allocates a stable name-matched stage lane; a second live slot for the same name is invalid. */ createDataOrderSlot(
    name: string,
  ): IPluginDataOrderSlot;
  /** Queues construction without publication; the owner must later commit or discard the capsule. */ prepareAdmissions(
    requestsInPublicationOrder: readonly IPluginAdmissionRequest[],
  ): Promise<IPluginPreparedAdmissions>;
  /** * Synchronously publishes one unused candidate if revision/lanes remain current; returns * receipts. */ commitPreparedAdmissions(
    prepared: IPluginPreparedAdmissions,
  ): readonly IRegistrationToken[];
  /** Rolls back an unpublished candidate; repeated or foreign discard returns empty cleanup detail. */ discardPreparedAdmissions(
    prepared: IPluginPreparedAdmissions,
  ): Promise<IPluginHostPhysicalCleanupResult>;
  /** Permanently retires this Host's lane; repeated retirement is harmless, foreign slots fail. */ retireDataOrderSlot(
    slot: IPluginDataOrderSlot,
  ): void;
  /** Captures exact live receipts, rejecting duplicates or an omitted required dependent. */ prepareUnUseBatch(
    receiptsInCleanupOrder: readonly IRegistrationToken[],
  ): IPluginPreparedRemovalBatch;
  /** Rechecks generations/dependencies, revokes all leaves, then waits for the fence and cleanup. */ commitPreparedUnUseBatch<
    TView,
  >(
    prepared: IPluginPreparedRemovalBatch,
    options: IPluginBatchRemovalOptions,
  ): Promise<IPluginBatchRemovalResult<TView>>;
}>;

export type IPluginHostCompositionSnapshot = Readonly<{
  /** Frozen extension publication with exact-registration liveness guards. */ readonly extensions: Readonly<
    Record<PropertyKey, unknown>
  >;
  /** Host config capability; reading a path still resolves current committed configuration. */ readonly config: IPluginHostConfigFor<
    readonly IPluginConstraint<any>[]
  >;
}>;

export type IRegistrationToken<
  TPlugin extends IPluginConstraint<any> = IPluginConstraint<any>,
> = object & Readonly<{ readonly __plugin?: TPlugin }>;

export type IRegistrationView<
  TPlugin extends IPluginConstraint<any> = IPluginConstraint<any>,
> = Readonly<{
  /** Exact-generation guarded extensions; they never follow a same-name replacement. */ readonly extensions: Readonly<
    IExtractPluginExt<TPlugin>
  >;
}>;

export declare const openComposition: (
  target: object,
) => IPluginHostCompositionIntegration<object>;

