  | IRuntimeBrowserWindowConnect
  | IRuntimeBrowserSharedWorkerConnect
  | IRuntimeBrowserRtcConnect;

export type IRuntimeBrowserConnectEvent = Readonly<{
  /** * Each supplied port receives a separate Core handshake and logical connection; ports stay * borrowed. */ ports: readonly ISharedWorkerPort[];
}>;

export type IRuntimeBrowserListen = Readonly<{
  /** Register the native connect callback; one scope may have only one active Browser Peer listener. */ addEventListener(
    type: 'connect',
    listener: (event: IRuntimeBrowserConnectEvent) => void,
  ): void;
  /** Remove that exact callback when the listener closes; this must not terminate the worker scope. */ removeEventListener(
    type: 'connect',
    listener: (event: IRuntimeBrowserConnectEvent) => void,
  ): void;
}>;

export type IRuntimeBrowserPeerOptions = Omit<
  IRuntimePeerOptions,
  'spawn' | 'connect' | 'listen'
> &
