    /** One borrowed Window, SharedWorker port or reliable ordered RTC channel; excludes listen. */ connect?: IRuntimeBrowserConnect;
    /** * SharedWorker connect-event scope; returns a listener before any page connects and excludes * connect. */ listen?: IRuntimeBrowserListen;
    /** * Caller cancellation releases unfinished handshake subscriptions without closing borrowed * carriers. A listener also retains this signal to close its accepts and sessions; omission * installs no caller cancellation source. */ signal?: IAdapterDefinitionPeerOptions<unknown>['signal'];
