const reports: IRpcWireErrorFailure[] = []
const wire = serializeRpcError(failure, {
  report: (entry) => {
    reports.push(entry)
  }
})
console.log(wire.name, wire.code)
console.log(reports.length, reports[0]?.field, reports[0]?.error === original)

