  /** Additional verifier used only when useBaseIdVerifyOnly is false; false rejects the peer. */ readonly identifier?: (
    context: IRpcConnectContext,
  ) => boolean | Promise<boolean>;
  /** Optional selector for a concrete registry candidate; an unknown selection fails TARGET_UNKNOWN. */ readonly receiverSelector?: (
    serverList: readonly IRpcServerMetadata[],
    context: {
      /** Local endpoint selecting a receiver. */ readonly endpointId: string;
      /** Logical target whose known candidates are supplied. */ readonly targetId: string;
      /** Whether selection serves send, dispatch or ping. */ readonly operation: IRpcOperation;
    },
  ) => string | undefined | Promise<string | undefined>;
};

export type IRpcConnectContext = {
  /** Direct envelope sender identity. */ readonly senderId: string;
  /** Envelope target that must match this endpoint. */ readonly targetId: string;
  /** Carrier-established direct peer address, when known. */ readonly peerId?: string;
  /** Native origin associated with the delivery. */ readonly origin?: string;
  /** Native carrier source object, when available. */ readonly source?: unknown;
  /** Incoming value available to the selected verifier. */ readonly data?: unknown;
  /** Transport platform label for the current delivery. */ readonly platform?: IRpcPlatformValue;
  /** Exclusive, multiplexed or broadcast routing shape. */ readonly topology?:
    | 'exclusive'
    | 'multiplexed'
    | 'broadcast';
};

export type IRpcConnectControl<TTargetId extends string = string> = {
  /** Read receiver metadata, optionally limited to one logical target. */ readonly getServerList: (
    targetId?: TTargetId,
  ) => readonly IRpcServerMetadata<TTargetId>[];
  /** Pin a known concrete receiver; anonymous or unknown targets cannot be pinned. */ readonly pinReceiver: (
    targetId: TTargetId,
    receiverId: string,
  ) => void;
  /** Clear the target's explicit receiver selection. */ readonly unpinReceiver: (
    targetId: TTargetId,
  ) => void;
  /** Collect candidates from one manual discovery query. */ query?: (
    targetId: TTargetId,
    options?: { readonly timeoutMs?: number; readonly signal?: IAbortSignal },
  ) => Promise<readonly IRpcDiscoveryCandidate<TTargetId>[]>;
  /** Subscribe to inbound manual queries and return that registration's remover. */ onQuery?: (
    listener: (query: IRpcInboundDiscoveryQuery<TTargetId>) => void | Promise<void>,
  ) => () => void;
  /** Register a validated manual discovery response. */ register?: (
    candidate: IRpcDiscoveryCandidate<TTargetId>,
  ) => void;
  /** Retire one concrete receiver, or all registered receivers for a target. */ unregister?: (
    targetId: TTargetId,
    receiverId?: string,
  ) => Promise<void>;
  /** Check one candidate through the canonical control owner. */ ping?: (
    candidate: IRpcDiscoveryCandidate<TTargetId>,
    options?: { readonly timeoutMs?: number; readonly signal?: IAbortSignal },
  ) => Promise<boolean>;
};

export type IRpcContext = {
  /** Serving endpoint identity lets mounted services exclude their own observation traffic. */ readonly localEndpointId: string;
  /** Present only after generation@1 directory admission for this actual runtime-profile task. */ readonly callerGeneration?: import('@migaia/rpc-contract').IRpcRuntimeGeneration;
  /** The final provider fence is the selected accepted identity, never an attempt counter. */ readonly targetGeneration?: import('@migaia/rpc-contract').IRpcRuntimeGeneration;
  /** Application parameters received for this invocation. */ readonly data: unknown;
  /** Cooperative provider cancellation signal; application I/O must observe it. */ readonly signal: INativeAbortSignal;
  /** Direct authenticated routing identity; forwarding never substitutes an earlier caller. */ readonly senderId: string;
  /** Remaining provider deadline, calculated with the original endpoint's monotonic clock. */ readonly timeoutMs?: number;
  /** Ordered signed forwarding nodes; absent on ordinary originating calls and foreign terminals. */ readonly route?: readonly string[];
  /** Opaque trace supplied by the caller; downstream sends must pass it explicitly. */ readonly trace?: string;
  /** Build a successful response and preserve the explicit transfer list for the physical sender. */ success(
    data?: unknown,
    options?: { readonly transfer?: readonly unknown[] },
  ): IRpcProviderResult;
  /** Build an application failure reply with its public message and code. */ failed(
    message: string,
    code: string,
  ): IRpcProviderResult;
  /** Send a notification through this invocation's existing routing owner without awaiting a reply. */ dispatchTo(input: {
    readonly id?: string;
    readonly method: string;
    readonly data: unknown;
  }): void;
};

export type IRpcContractCapability = IRpcContractConfig & {
  /** Validate one method side; invalid data throws a schema validation failure. */ readonly validateData: (
    method: string,
    side: 'params' | 'result',
    data: unknown,
  ) => void;
};

export type IRpcContractConfig = {
  /** Application version written to routed messages, when configured. */ readonly version?: string;
  /** Allowed incoming application versions; omission adds no explicit allow-list. */ readonly acceptVersions?: readonly string[];
  /** Optional positive safe-integer application identifier limit. */ readonly maxIdentifierLength?: number;
  /** * Method-name map of parameter/result parsers; undeclared methods have no added schema * validation. */ readonly schemas?: Readonly<
    Record<string, IRpcMethodSchema>
  >;
};

export type IRpcDiscoveryCandidate<TTargetId extends string = string> = {
  /** Discovery request that produced this candidate. */ readonly queryId: string;
  /** Logical service target associated with the reply. */ readonly targetId: TTargetId;
  /** Concrete receiver address, when identifiable. */ readonly receiverId?: string;
  /** Candidate response payload. */ readonly data: unknown;
  /** Carrier on which the candidate was observed. */ readonly platform: IRpcPlatformValue;
  /** Native delivery origin, when available. */ readonly origin?: string;
};

export type IRpcDiscoveryControl<TTargetId extends string = string> = {
  /** Read the endpoint's receiver registry, optionally for one target. */ readonly getServerList: (
    targetId?: TTargetId,
  ) => readonly IRpcServerMetadata<TTargetId>[];
  /** Choose one known concrete receiver for subsequent target resolution. */ readonly pinReceiver: (
    targetId: TTargetId,
    receiverId: string,
  ) => void;
  /** Return the target to ordinary receiver selection. */ readonly unpinReceiver: (
    targetId: TTargetId,
  ) => void;
};

export type IRpcEndpoint<
  TTargetId extends string = string,
  TMode extends IRpcDiscoveryMode = 'automatic',
  TPing extends boolean = boolean,
> = {
  /** * Register one request handler and return this endpoint; a duplicate name throws * PROVIDER_DUPLICATED without replacing it. */ provide(
    method: string,
    provider: IRpcProvider,
  ): IRpcEndpoint<TTargetId, TMode, TPing>;
  /** Subscribe to notification events; return the remover for this exact registration. */ on(
    event: string,
    listener: IRpcEventListener,
  ): () => void;
  /** * Request one target result; timeout, cancellation, remote and transport failures reject the * Promise. */ send<
    T,
  >(
    targetId: TTargetId,
    method: string,
    data: unknown,
    options?: ISendOptions,
  ): Promise<T>;
  /** Request every configured target and collect each fulfillment or rejection separately. */ sendAll<
    T,
  >(
    method: string,
    data: unknown,
    options?: ISendOptions,
  ): Promise<IRpcFanoutResult<T>>;
  /** Send a notification without a reply Promise; delivery failures are diagnostic. */ dispatch(
    targetId: TTargetId,
    method: string,
    data: unknown,
  ): void;
  /** Notify each configured target without collecting remote results. */ dispatchAll(
    method: string,
    data: unknown,
  ): void;
  /** Submit one atomic request group to an actually admitted native peer. */ group(
    targetId: TTargetId,
    steps: IRpcRuntimeGroupSteps,
    options?: IRpcRuntimeGroupOptions,
  ): Promise<readonly IRpcRuntimeStepOutcome[]>;
  /** Read a logical key's original stored outcome without executing its providers again. */ outcome(
    targetId: TTargetId,
    idempotencyKey: string,
  ): Promise<IRpcRuntimeOutcomeResult>;
  /** Announce a bounded drain window to one peer without closing the channel in core. */ announceClose(
    targetId: TTargetId,
    options: { readonly drainMs: number; readonly receiverId?: string },
  ): Promise<void>;
  /** Mode-specific connection and receiver-selection controls. */ readonly connect: IRpcConnectControlForMode<
    TTargetId,
    TMode
  >;
  /** Local receiver inspection and pinning view. */ readonly discovery: IRpcDiscoveryControl<TTargetId>;
  /** Subscribe to local endpoint diagnostics; registration removal is caller-owned. */ readonly hooks: {
    on(listener: IRpcHook): () => void;
  };
  /** * Retire this endpoint, settle pending work and release owned resources; repeated calls share * terminal cleanup. */ dispose(): Promise<void>;
} & IRpcPingEndpointSurface<TPing>;

export type IRpcError = {
  readonly source: string;
  readonly code: IRpcCoreErrorCode;
  readonly cause?: unknown;
};

export type IRpcFactoryConfig<
  TTargetId extends string = string,
  TMiddlewares extends readonly IRpcMiddleware[] = readonly IRpcMiddleware[],
  TFeatures extends readonly IRpcFeature[] = readonly IRpcFeature[],
  TEnvelope extends IRpcEnvelope = IRpcEnvelope,
  TEncoded = unknown,
  TFrame = TEncoded,
> = {
  /** Stable local endpoint identity included in every routed protocol envelope. */ readonly id: string;
  /** * Endpoint monotonic clock and timers; the same injected instance also drives PluginHost * deadlines. `now()` must return finite non-negative milliseconds and is never read as an epoch. */ readonly scheduler?: import('@migaia/utils/scheduler').IScheduler;
  /** * Endpoint wall clock; only produces wire `sentAt` and hook event `at` diagnostics. `timestamp()` * must return non-negative safe-integer epoch milliseconds. Defaults to the host wall clock. */ readonly wallClock?: import('@migaia/utils/scheduler').IWallClock;
  /** Optional known-peer seed; automatic discovery may resolve additional target ids lazily. */ readonly targetIds?: readonly TTargetId[];
  /** Transport receives exactly the selected framer output, except an explicit opaque sink. */ readonly transport?: IRpcTransport<TFrame>;
  /** Semantic descriptor feeding the codec edge in the canonical endpoint pipeline. */ readonly protocol?: IRpcProtocol<
    TEnvelope,
    string,
    number
  >;
  /** Codec whose output must match the selected framer input exactly. */ readonly codec?: ICodec<
    TEnvelope,
    TEncoded
  >;
  /** Framer whose output is the value delivered to the selected transport. */ readonly framer?: IRpcFramer<
    TEncoded,
    TFrame,
    string,
    number
  >;
  /** Initial provider methods registered before endpoint construction completes. */ readonly provider?: Readonly<
    Record<string, IRpcProvider>
  >;
  /** Provider concurrency budgets; defaults to 256 global and 64 per peer. */ readonly providerLimits?: IRpcProviderLimits;
  /** Optional store and session scope used only for keyed provider requests. */ readonly idempotency?: IRpcIdempotencyConfig;
  /** Bounds outbound identifier replay reservations for this endpoint. */ readonly replay?: {
    /** Maximum retained outbound request identifiers; defaults to 4096. */ readonly maxEntries?: number;
    /** Retention time for outbound request identifiers; defaults to 310 seconds. */ readonly ttlMs?: number;
  };
  /** Ordered middleware tuple installed atomically during endpoint construction. */ readonly middlewares: TMiddlewares;
  /** Finite immutable tuple of user-defined features installed by the canonical Host batch. */ readonly features?: TFeatures;
  /** Cancellation and deadline controls for middleware installation and rollback. */ readonly construction?: {
    /** Aborts construction while still rolling back every installed middleware. */ readonly signal?: IAbortSignal;
    /** Bounds endpoint construction, or disables the deadline when explicitly `false`. */ readonly timeoutMs?:
      | number
      | false;
  };
};

export type IRpcFanoutResult<TResult> = {
  /** Successful results indexed by target identity. */ readonly fulfilled: Partial<
    Record<string, TResult>
  >;
  /** Failures indexed by target identity, retaining the original rejection values. */ readonly rejected: Partial<
    Record<string, unknown>
  >;
};

export type IRpcFeatureConfig = {
  /** Legacy remote-cancellation role flag. */ readonly abort?: boolean;
  /** Legacy explicit-ping role flag. */ readonly ping?: boolean;
};

export type IRpcFeatureDefinition<
  TSurface extends object = object,
  TDependencies extends IFeatureRecord = Record<never, never>,
  TExpose extends object = Record<never, never>,
> = Readonly<{
  /** Synchronous native Feature factory evaluated for this Host registration. */ readonly install: IFeatureFactory<
    TExpose,
    TDependencies,
    TSurface
  >;
  /** Direct Feature dependencies supplied to the factory; omission means no declared edges. */ readonly dependencies?: TDependencies;
  /** Optional exact endpoint keys this output publishes, captured before construction. */ readonly publicKeys?: readonly (keyof TSurface &
    string)[];
  /** Optional Feature-policy conflict names checked during composition admission. */ readonly conflicts?: readonly string[];
}>;

export type IRpcFeatureSurface<TFeatures extends readonly IRpcFeature[]> =
  IUnionToIntersection<
    TFeatures[number] extends IRpcFeature<infer TSurface> ? TSurface : never
  >;

export type IRpcHookEvent = {
  /** Stable event name identifying the diagnostic scenario. */ readonly name: string;
  /** Wall-clock epoch milliseconds used for diagnostic presentation. */ readonly at: number;
  /** Endpoint that emitted this observation. */ readonly localId: string;
  /** Semantic failure code when this event represents a failure. */ readonly code?: string;
  /** Original local diagnostic failure, when supplied. */ readonly error?: unknown;
  /** Field associated with a validation or callback failure. */ readonly field?: string;
  /** Rate-limited, local-only replay capacity evidence; never serialized onto RPC frames. */ readonly detail?: IRpcReplayCapacityDetail;
  /** Relative peer drain announced by a validated close control frame. */ readonly durationMs?: number;
  /** Contract diagnostic detail when relevant to this event. */ readonly contract?: unknown;
  /** Control-variation diagnostic value when present. */ readonly variation?: unknown;
  /** Logical target involved in this observation. */ readonly targetId?: string;
  /** Selected concrete receiver, if known. */ readonly receiverId?: string;
  /** Requester involved in a discovery observation. */ readonly requesterId?: string;
  /** Candidate receiver identities associated with the event. */ readonly receiverIds?: readonly string[];
  /** Whether receiver selection observed multiple eligible candidates. */ readonly ambiguous?: boolean;
  /** Number of observed discovery responses, when supplied. */ readonly responseCount?: number;
};

export type IRpcHooksConfig = {
  /** Initial hook or ordered hook array; defaults to no listeners. */ readonly listeners?:
    | IRpcHook
    | readonly IRpcHook[];
  /** Optional synchronous reporter for hook failures; omission uses Core's diagnostic policy. */ readonly onHookError?: (
    error: unknown,
    event: IRpcHookEvent,
  ) => void;
};

export type IRpcIdempotencyClaim =
  | Readonly<{
      /** * Claimed owns execution; pending waits for the original owner; done replays retention; full * refuses admission. */ status: 'claimed';
      /** Settle this exact claim once with its outcome and settlement-relative monotonic time. */ settle: (
        outcome: IRpcIdempotencyOutcome,
        now: number,
      ) => void;
      /** Release an unsettled claim and resolve its waiting observers with undefined. */ release: () => void;
    }>
  | Readonly<{
      /** * Claimed owns execution; pending waits for the original owner; done replays retention; full * refuses admission. */ status: 'pending';
      /** * Original completed outcome or pending observation; unavailable means the body was not * retained. */ outcome: Promise<
        IRpcIdempotencyOutcome | 'unavailable' | undefined
      >;
    }>
  | Readonly<{ status: 'done'; outcome: IRpcIdempotencyOutcome | 'unavailable' }>
  | Readonly<{ status: 'full' }>;

export type IRpcIdempotencyConfig = Readonly<{
  /** Borrowed store for keyed provider executions; omission selects the endpoint-owned default. */ store?: IRpcIdempotencyStore;
  /** Compute an authenticated deduplication namespace from admitted token and sender identity. */ scope?: (
    admission: Readonly<{ token: string; senderId: string }>,
  ) => string;
}>;

export type IRpcIdempotencyOutcome = Readonly<
  | { ok: true; data?: IRpcPortableValue }
  | {
      /** False selects a failed application outcome retained for replay. */ ok: false;
      /** Stable application failure code retained with this original outcome. */ code: string;
      /** Application failure message retained for replay. */ message: string;
      /** Optional portable application result or failure detail. */ data?: IRpcPortableValue;
      /** Optional serialized failure chain retained for the original result. */ error?: IRpcSerializedError;
    }
>;

export type IRpcIdempotencyStore = Readonly<{
  /** * Atomically claim a scoped logical key, observe its existing owner/result, or refuse capacity. * Fingerprint mismatch rejects the contract. */ claim: (
    scope: string,
    key: string,
    now: number,
    fingerprint?: string,
  ) => IRpcIdempotencyClaim;
  /** * Optional outcome-lookup extension; a legacy store without lookup cannot advertise outcome * semantics. */ lookup?: (
    scope: string,
    key: string,
    now: number,
  ) => IRpcIdempotencyLookup;
  /** Opt-in store facts describe this actual owner; ordinary claims never create or read an epoch. */ readRuntimeFacts?: () => IRpcRuntimeStore;
}>;

export type IRpcInboundDiscoveryQuery<TTargetId extends string = string> = {
  /** Logical target requested by the remote query. */ readonly targetId: TTargetId;
  /** Query application payload. */ readonly data: unknown;
  /** Carrier that delivered the query. */ readonly platform: IRpcPlatformValue;
  /** Native delivery origin, when supplied. */ readonly origin?: string;
  /** Reply with optional data and resolve whether this query response was accepted. */ readonly accept: (
    data?: unknown,
  ) => Promise<boolean>;
  /** Reply with an optional rejection reason and resolve whether it was sent. */ readonly reject: (
    reason?: string,
  ) => Promise<boolean>;
};

export type IRpcMethodSchema = {
  /** Validate input before provider execution or outbound sending. */ readonly params: IRpcSchema;
  /** Validate successful response data before accepting it. */ readonly result: IRpcSchema;
};

export type IRpcMiddlewareCore<
  TFeatures extends IFeatureRecord = Record<never, never>,
  TFeatureExpose extends object = Record<never, never>,
> = Readonly<{
  /** Local endpoint identity captured for this registration. */ readonly id: IRpcPluginCore['id'];
  /** Selected physical adapter; this view does not transfer resource ownership. */ readonly transport: IRpcPluginCore['transport'];
  /** Original registration cancellation signal. */ readonly signal: IRpcPluginCore['signal'];
  /** Publish local diagnostics through the endpoint hook owner. */ readonly hooks: IRpcPluginCore['hooks'];
  /** * Register cleanup during install; using it before the install scope exists rejects * configuration. */ readonly own: IRpcPluginInstallScope['own'];
  /** Resolved outputs from the explicitly declared Feature dependencies. */ readonly features: IFeatureOutputs<TFeatures>;
  /** Host bridge declared by this middleware for its Feature factories. */ readonly featureExpose: TFeatureExpose;
}>;

export type IRpcMiddlewareDescriptor<
  TExtension extends Record<string, unknown> = Record<never, never>,
  TPublic extends object = Record<never, never>,
  TFeatureExpose extends object = Record<never, never>,
> = Readonly<{
  /** * Optional asynchronous extension setup; resources acquired here belong to the construction * scope. */ readonly install?: () =>
    | TExtension
    | PromiseLike<TExtension>;
  /** Optional synchronous public projection; a Promise is not an exposed surface. */ readonly expose?: () => TPublic &
    (TPublic extends PromiseLike<unknown> ? never : unknown);
  /** Optional synchronous host bridge for the declared Feature dependencies. */ readonly featureExpose?: () => TFeatureExpose &
    (TFeatureExpose extends PromiseLike<unknown> ? never : unknown);
}>;

export type IRpcPingCapability = {
  /** Enables explicit liveness control without scheduling a heartbeat. */ readonly enabled: true;
};

export type IRpcPingEndpointSurface<TPing extends boolean> = boolean extends TPing
  ? {
      /** Probe one selected receiver; the Promise resolves true only for the admitted pong. */ ping(
        targetId: string,
        receiverId?: string,
        options?: IRpcPingOptions,
      ): Promise<boolean>;
      /** Probe configured receivers and retain individual successes/failures. */ pingAll(): Promise<
        IRpcFanoutResult<boolean>
      >;
    }
  : TPing extends true
    ? {
        /** Probe one selected receiver; the Promise resolves true only for the admitted pong. */ ping(
          targetId: string,
          receiverId?: string,
          options?: IRpcPingOptions,
        ): Promise<boolean>;
        /** Probe configured receivers and retain individual successes/failures. */ pingAll(): Promise<
          IRpcFanoutResult<boolean>
        >;
      }
    : {};

export type IRpcPingOptions = {
  /** Explicit finite non-negative budget, false for no deadline, or omitted to inherit policy. */ readonly timeoutMs?:
    | number
    | false;
  /** Cancel local liveness waiting; cancellation is not proof of remote termination. */ readonly signal?: IAbortSignal;
};

export type IRpcPlugin<TComponents extends object = {}> = {
  /** Unique middleware name; duplicates reject endpoint construction. */ readonly name: string;
  /** Static dependency, route and publication claims checked before activation. */ readonly metadata: IRpcPluginMetadata;
  /** Discovery mode retained on the native descriptor for factory conditional typing. */ readonly discoveryMode?: IRpcDiscoveryMode;
  /** Ping capability retained on the native descriptor for factory conditional typing. */ readonly pingCapability?: true;
  /** Runtime component slots stay opaque until tuple selection proves their exact contribution. */ readonly transport?: unknown;
  /** Optional semantic protocol component contributed to the pipeline. */ readonly protocol?: unknown;
  /** Optional codec component contributed to the pipeline. */ readonly codec?: unknown;
  /** Optional framing component contributed to the pipeline. */ readonly framer?: unknown;
  /** Install under the construction scope; acquired resources roll back on failure. */ readonly install: (
    scope: IRpcPluginInstallScope,
  ) => IRpcPluginInstallResult | Promise<IRpcPluginInstallResult>;
} & Readonly<TComponents>;

export type IRpcPluginClaims = {
  /** Inbound protocol routes reserved by this middleware. */ readonly routes: readonly string[];
  /** Named capabilities contributed to the composition graph. */ readonly provides: readonly string[];
  /** Required capability names that must be available in the composition. */ readonly consumes: readonly string[];
  /** Exact endpoint extension keys this middleware publishes. */ readonly publicKeys: readonly string[];
  /** Exact exposed capability keys used during admission. */ readonly exposedKeys: readonly string[];
  /** Whether this role commits the prepared ingress activation. */ readonly activator: boolean;
};

export type IRpcPluginInstallResult = {
  /** Endpoint extension values whose keys must match the declared publication claim. */ readonly extension: Readonly<
    Record<string, unknown>
  >;
  /** Shared port values whose keys must match declared providers. */ readonly ports: Readonly<
    Record<PropertyKey, unknown>
  >;
};

export type IRpcPluginInstallScope = {
  /** Stable local endpoint identity. */ readonly id: string;
  /** Selected physical transport; ownership remains with the endpoint kernel. */ readonly transport: IRpcTransport;
  /** Construction/registration cancellation signal. */ readonly signal: INativeAbortSignal;
  /** Emit a local diagnostic through the endpoint hook owner. */ readonly hooks: (
    event: IRpcHookEvent,
  ) => void;
  /** Read an admitted shared composition port. */ readonly getPort: (
    key: PropertyKey,
  ) => unknown;
  /** Register a release operation with this install scope for rollback and normal disposal. */ own<
    T,
  >(
    resource: T,
    release: () => void | Promise<void>,
  ): T;
};

export type IRpcPluginMetadata = {
  /** Static route, dependency and publication claims checked before installation. */ readonly claims: IRpcPluginClaims;
  /** Shared port keys this middleware owns, when declared. */ readonly sharedProvides?: readonly PropertyKey[];
  /** Shared ports required from other installed roles. */ readonly sharedConsumes?: readonly PropertyKey[];
  /** Optional shared ports that may be absent. */ readonly sharedOptionalConsumes?: readonly PropertyKey[];
};

export type IRpcProtocolCapability = {
  /** Encode an admitted semantic value for the next pipeline edge. */ readonly encode: (
    value: unknown,
  ) => unknown;
  /** Restore an encoded value before protocol admission. */ readonly decode: (
    value: unknown,
  ) => unknown;
  /** Declared intermediate representation, when provided. */ readonly encodedType?:
    | 'any'
    | 'string'
    | 'uint8array';
  /** Whether this capability explicitly preserves input identity. */ readonly identity?: boolean;
};

export type IRpcProtocolConfig = {
  /** Optional legacy outbound transform. */ readonly encode?: (
    value: unknown,
  ) => unknown;
  /** Optional legacy inbound transform. */ readonly decode?: (
    value: unknown,
  ) => unknown;
  /** Legacy declared representation: any value, text, or Uint8Array. */ readonly encodedType?:
    | 'any'
    | 'string'
    | 'uint8array';
};

export type IRpcProvider = (
  context: IRpcContext,
) => IRpcProviderResult | Promise<IRpcProviderResult>;

export type IRpcProviderLimits = {
  /** Positive safe-integer maximum active provider work across peers; defaults to 256. */ readonly maxGlobal?: number;
  /** Positive safe-integer maximum active provider work per verified peer; defaults to 64. */ readonly maxPerPeer?: number;
  /** * Maximum completed inbound request tombstones retained per verified peer; defaults to 1024. * Configure a known session workload without changing concurrency or the global replay ceiling. */ readonly maxReplayEntriesPerPeer?: number;
  /** * Notify the local connection owner of a refused provider execution. The provider is not invoked; * observer failures are reported through endpoint hooks without replacing the existing OVERLOADED * result. No wire data is inspected. */ readonly onRejected?: (
    rejection: IRpcProviderRejection,
  ) => void | Promise<void>;
};

export type IRpcProviderRejection = Readonly<{
  /** Original verified-peer quota identity used for this local admission. */ verifiedPeerKey: string;
  /** Original invocation controller identity associated with the refusal. */ controllerKey: string;
  /** Requested application method that was not invoked. */ method: string;
  /** * Specific local quota/replay/binding reason; the wire OVERLOADED code alone does not distinguish * it. */ reason: RpcProviderRejectionReason;
}>;

export type IRpcProviderResult =
  | {
      /** Successful context-owned settlement. */ readonly ok: true;
      /** Application response value. */ readonly data?: unknown;
      /** Optional physical transfer list for this response. */ readonly transfer?: readonly unknown[];
    }
  | {
      /** Failed context-owned settlement. */ readonly ok: false;
      /** Application failure explanation. */ readonly message: string;
      /** Stable application failure code. */ readonly code: string;
    };

export type IRpcReplayCapacityDetail = Readonly<{
  /** Inbound or outbound owner whose bounded identifier ledger refused admission. */ readonly namespace: RpcReplayCapacityNamespace;
  /** Specific replay-capacity refusal, separate from provider concurrency. */ readonly reason: Extract<
    RpcProviderRejectionReason,
    'replayLedgerFull' | 'outboundReplayFull'
  >;
  /** Currently retained entries in that ledger. */ readonly occupancy: number;
  /** Configured maximum entry count. */ readonly limit: number;
  /** Present only for inbound capacity, without identifying the verified peer. */ readonly peerOccupancy?: number;
  /** Configured per-verified-peer limit when this is inbound capacity. */ readonly peerLimit?: number;
}>;

export type IRpcRuntimeGroupSteps = Extract<
  IRpcRuntimeEnvelope,
  { kind: 'runtime-group' }
>['steps'];

export type IRpcSchema<T = unknown> = {
  /** Accept or throw synchronously for one value. */ parse(value: unknown): T;
};

export type IRpcSchemaIssue = {
  /** Object keys and array indices leading to the invalid value. */ readonly path: readonly (
    | string
    | number
  )[];
  /** Schema-supplied explanation of the validation failure. */ readonly message: string;
  /** Optional schema-specific diagnostic code. */ readonly code?: string;
};

export type IRpcServerMetadata<TTargetId extends string = string> = {
  /** Logical service target registered by this receiver. */ readonly targetId: TTargetId;
  /** Concrete receiver identity usable for pinning. */ readonly receiverId: string;
  /** Optional instance discriminator established during verification. */ readonly uniqueTargetId?: string;
  /** Carrier platform on which this receiver was observed. */ readonly platform: IRpcPlatformValue;
  /** Native origin retained for the receiver, when supplied. */ readonly origin?: string;
  /** * Endpoint monotonic time (the endpoint scheduler's `now()`) when the receiver was registered. * Comparable only with other metadata of the same endpoint or with `IRpcTimePort.now()`. */ readonly registeredAt: number;
  /** Endpoint monotonic time of the last observation; same comparison domain as `registeredAt`. */ readonly lastSeenAt: number;
  /** Whether the logical target is explicitly pinned to this receiver. */ readonly pinned: boolean;
  /** Active, stale or unregistered registry state. */ readonly status: IRpcCandidateStatus;
};

export type IRpcTimeoutCapability = IRpcTimeoutConfig & {
  /** * Select an explicit per-call override or the installed default; preserve false and undefined for * the operation owner to interpret. */ readonly resolveTimeout: (
    override?: number | false,
  ) => number | false | undefined;
};

export type IRpcTimeoutConfig = {
  /** Finite non-negative milliseconds or false; omission in timeout({}) leaves calls unbounded. */ readonly timeoutMs?:
    | number
    | false;
};

export type IRpcUniqueTargetIdContext = {
  /** Local endpoint requesting an instance discriminator. */ readonly endpointId: string;
  /** Platform of the configured physical transport. */ readonly platform: IRpcPlatformValue;
