  readonly policy?: IConcurrencyPolicy;
  /** * Wraps the original logical loop so one pipeline terminal supplies fixed input before native * work. */ readonly execute?: (
    captured: IOperationContext & { readonly conflictPolicy?: IConflictPolicy },
    invokeOriginalLoop: () => Promise<Awaited<TResult>>,
  ) => Awaited<TResult> | PromiseLike<Awaited<TResult>>;
  /** * Wraps each actual native commit attempt. Acquisition retries stay within the current stage; * commit conflicts finish its catch/finally before policy and another stage. Mutually exclusive * with execute. A stage may halt or recover by returning without rethrowing the exact conflict. */ readonly executeAttempt?: (
    captured: IOperationContext & { readonly conflictPolicy?: IConflictPolicy },
    invokeOriginalAttempt: () => Promise<Awaited<TResult>>,
  ) => Awaited<TResult> | PromiseLike<Awaited<TResult>>;
  /** Runs one original pipeline within this call's budget before deriving its fixed-input locks. */ readonly prepare?: (
    captured: IOperationContext & { readonly conflictPolicy?: IConflictPolicy },
  ) => void | PromiseLike<void>;
