export declare const StorageContractErrorCode: Readonly<{
  /** * A public argument or descriptor fails contract shape validation. Applies to codec descriptors, * capability descriptors, key domains, transaction options, and operation contexts. * * Enforces runtime public argument and contract shape validation. Adapter-specific configuration * validation uses the web `INVALID_CONFIG` code instead. * * The caller corrects the argument before retrying. The failure persists until the argument * changes. */ readonly invalidArgument: 'INVALID_ARGUMENT';
  /** * An `IStorageKey` violates the key domain through an invalid type, excessive depth, node count * or binary bytes, a cycle, or an empty array. * * Enforces contract key validation. * * The caller corrects the key rather than retrying the same invalid key. */ readonly invalidKey: 'INVALID_KEY';
  /** * An operation requires a capability that the current backend does not provide. Examples include * failed `asRecordStore` narrowing and a structured codec on a text-only backend. * * Enforces contract capability narrowing. * * The caller checks `capabilities` or `isRecordStore`, or selects a backend with the required * capability. The operation does not silently fall back. */ readonly unsupported: 'UNSUPPORTED_CAPABILITY';
  /** * A storage operation runs after the store is disposed, violating the lifecycle contract. * * Enforces contract lifecycle semantics. * * The caller creates a new store instead of reusing the closed instance. */ readonly disposed: 'STORE_DISPOSED';
  /** * `IOperationContext.signal` cancels an operation or `timeoutMs` expires. * * Enforces contract cancellation semantics. * * The caller handles the result as cancellation. A write that has entered atomic commit reports * the actual commit result rather than claiming rollback. */ readonly aborted: 'ABORTED';
  /** * A strict query contains client-only steps; inspect its plan or remove strictness before * reading. */ readonly queryNotPushable: 'QUERY_NOT_PUSHABLE';
  /** FirstOrThrow exhausted the query; use first or maybe when absence is expected. */ readonly queryEmptyResult: 'QUERY_EMPTY_RESULT';
  /** A bounded vector scorer threw or rejected; inspect its unchanged original cause. */ readonly rerankFailed: 'RERANK_FAILED';
  /** A scorer must return one finite numeric score per actual hit; correct its result. */ readonly rerankResultInvalid: 'RERANK_RESULT_INVALID';
  /** A durable replay cursor was evicted; invalidate the full cache and subscribe from now. */ readonly changeCursorExpired: 'CHANGE_CURSOR_EXPIRED';
  /** A genuine policy threw or returned an invalid/inapplicable decision; correct the policy. */ readonly concurrencyPolicyFailed: 'CONCURRENCY_POLICY_FAILED';
  /** A logical admission or physical operation deadline expired; resources have finished cleanup. */ readonly lockTimeout: 'LOCK_TIMEOUT';
  /** A real acquisition conflict was rejected by policy; choose a different key or retry later. */ readonly lockRejected: 'LOCK_REJECTED';
  /** A completed rollback reported a write conflict that policy declined to retry; reload data. */ readonly writeConflict: 'WRITE_CONFLICT';
  /** A backend confirmed another attempt replaced its expired lock; retry with a fresh attempt. */ readonly lockLost: 'LOCK_LOST';
  /** Saved data is not an own-property version/state envelope; correct the archive or writer. */ readonly envelopeInvalid: 'ENVELOPE_INVALID';
  /** The archive is newer than this code or older than its migration range; update the plan. */ readonly versionUnsupported: 'VERSION_UNSUPPORTED';
  /** Migration target keys contain a gap, alias, or out-of-range version; correct the steps. */ readonly migrationGap: 'MIGRATION_GAP';
  /** A migration step failed or returned a thenable to the sync entry; inspect the original cause. */ readonly migrationFailed: 'MIGRATION_FAILED';
}>;

