      /** Defaults to false; true rejects conflicting projected keys inside the authoritative commit. */ readonly unique?: boolean;
      /** * Defaults to false; true projects individual array elements and is unavailable for composite * paths. */ readonly multiEntry?: boolean;
      /** * Projection revision; path projections default to 1, while custom select must supply a * positive revision. */ readonly revision?: number;
    }
  | {
      /** Ordered domain paths forming one composite array key. */ readonly paths: readonly IObjectPathInput<TDomain>[];
      /** Defaults to false; true rejects conflicting projected keys inside the authoritative commit. */ readonly unique?: boolean;
      /** * Defaults to false; true projects individual array elements and is unavailable for composite * paths. */ readonly multiEntry?: false;
      /** * Projection revision; path projections default to 1, while custom select must supply a * positive revision. */ readonly revision?: number;
    }
  | {
      /** * Synchronous projection returning a single key, multiple keys or undefined to omit this * record. */ readonly select: (
        value: TDomain,
      ) =>
        | { readonly kind: 'single'; readonly key: IStorageKey }
        | { readonly kind: 'multiple'; readonly keys: readonly IStorageKey[] }
        | undefined;
      /** Defaults to false; true rejects conflicting projected keys inside the authoritative commit. */ readonly unique?: boolean;
      /** * Projection revision; path projections default to 1, while custom select must supply a * positive revision. */ readonly revision: number;
    };

