    try {
      console.log(object.info.size) // 4
      console.log([...(await object.bytes())]) // [20, 30]
    } finally {
      await object.dispose()
    }
  }
  await objects.remove('sample')
} finally {
  await host.dispose()
}

import { createStorageHost } from '@migaia/storage-host'
