  /** Borrowed reactive Runtime, default defaultRuntime, used for the returned Resource. */ readonly runtime?: IRuntime;
  /** Optional synchronous transfer-list selector per input; omitted means no explicit transfer list. */ readonly transfer?: (
    input: Input,
  ) => readonly unknown[];
};

