  /** Number of the latest start attempt; a successful start identifies the serving unit. */ readonly generation: number;
  /** * Starts the unit, retrying through backoff, and resolves with a stable answer: `ready` with the * unit, `stopped` (possibly with a budget rejection) or `terminal`. Unit failures never reject; * only a disposed supervisor rejects. Calling it while ready or starting joins the same answer. */ start(): Promise<
    IReadyOutcome<THandle>
  >;
