  >;
  /** * Replaces the serving unit, optionally with a new spec. `stop-then-start` (default) stops first; * `start-then-switch` switches only after the new unit is ready, then stops the old one. A failed * replacement resolves `failed` or `rejected` and leaves a still-serving old unit in place. */ replace(options?: {
    readonly strategy?: ReplaceStrategy;
    readonly spec?: TSpec;
  }): Promise<IReplaceOutcome>;
  /** Reads state, last exit, failure window, health and degradation without side effects. */ inspect(): ISupervisorSnapshot;
  /** Registers an event listener and returns its unsubscribe function; listener errors are reported. */ subscribe(
    listener: (event: ISupervisorEvent<THandle>) => void,
  ): () => void;
