  /** Restart mode and bounded exponential backoff after profile-classified retryable exit. */ readonly restart?: {
    /** Selects never, on-failure or always restart after exit; defaults to on-failure. */ readonly mode?: RestartMode;
    /** First automatic restart delay in scheduler milliseconds; defaults to 250. */ readonly initialDelayMs?: number;
    /** Multiplier for successive restart delays; defaults to 2 and remains bounded by maxDelayMs. */ readonly factor?: number;
    /** Upper bound on exponential restart delay in milliseconds; defaults to 30000. */ readonly maxDelayMs?: number;
