        /** Scheduler milliseconds to wait before admitting a new generation. */ readonly afterMs: number;
      };
  /** * Ordered shutdown policy for draining application work, requesting exit and finally reaping the * unit. */ readonly stop?: {
    /** Optional cancellable drain callback invoked before profile-specific termination. */ readonly beforeTerminate?: (
      unit: THandle,
      signal: INativeAbortSignal,
      remainingMs: () => number,
    ) => PromiseLike<void>;
    /** Maximum application drain time before termination proceeds; defaults to 5000 milliseconds. */ readonly drainTimeoutMs?: number;
    /** Maximum wait for graceful actual exit before hard termination; defaults to 5000 milliseconds. */ readonly exitTimeoutMs?: number;
    /** Maximum wait for actual exit after hard termination; defaults to 5000 milliseconds. */ readonly reapTimeoutMs?: number;
  };
  /** * Periodic cancellable health checks for a ready unit; repeated failure invalidates that * generation. */ readonly health?: {
